-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 8 (271-300)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- FORENSIC: THERMAL INJURIES (271-275)
    (v_topic_id, 'What is the "Rule of Nines" used for in burn patients?', '["Estimating the depth of the burn", "Rapidly estimating the percentage of Total Body Surface Area (TBSA) involved in the burn", "Calculating the age of the burn", "Estimating the survival time"]', 1, 'The Rule of Nines is a clinical tool to estimate burn size: Head (9%), each Arm (9%), each Leg (18%), Front of Torso (18%), Back of Torso (18%), and Perineum (1%). It helps guide fluid resuscitation.'),
    (v_topic_id, 'How do "Scalds" differ from "Flame Burns"?', '["Scalds are caused by dry heat", "Scalds are caused by moist heat (liquid or steam), do not singe hair, and typically show ''line of tide'' or ''drip'' patterns", "Scalds are always 4th degree", "Scalds only occur in children"]', 1, 'Scalds result from hot liquids or steam. They often show a "splash" or "drip" pattern and, importantly, do NOT singe hair (unlike flame burns). Presence of uniform depth and sharp margins in a child should raise suspicion for non-accidental injury (immersion scald).'),
    (v_topic_id, 'A "Pugilistic Attitude" in a body found in a fire is due to?', '["Active fighting before death", "Post-mortem heat-induced contraction of the muscles (flexors are stronger than extensors), causing the limbs to flex like a boxer", "Muscle relaxation", "Spinal cord injury"]', 1, 'The pugilistic (boxer) stance is a purely physical phenomenon caused by the coagulation of muscle proteins and contraction of the muscle fibers due to high heat. It does not indicate the person was fighting or even alive when the fire started.'),
    (v_topic_id, 'What is a "Heat Hematoma" (extradural)?', '["A brain hemorrhage from a blow to the head", "An artifact caused by heat-induced shrinkage of the brain and blood being forced out of the skull into the extradural space", "A sign of homicide", "A collection of CSF"]', 1, 'Heat hematoma is a post-mortem artifact seen in charred bodies. It can mimic a traumatic extradural hemorrhage. It is typically brown, friable, and "honeycombed" with gas bubbles, whereas a traumatic hematoma is firm, dark red, and usually associated with a skull fracture.'),

    -- FORENSIC: SEROLOGY & SEXUAL ASSAULT (276-285)
    (v_topic_id, 'In cases of suspected sexual assault, which enzyme is screened for in vaginal swabs to detect the presence of seminal fluid?', '["Amylase", "Acid Phosphatase (specifically Prostatic Acid Phosphatase)", "Lipase", "Creatine Kinase"]', 1, 'Prostatic Acid Phosphatase (PAP) is present in high concentrations in seminal fluid. It is used as a screening test. Confirmation of semen is usually done by identifying spermatozoa or detecting Prostate Specific Antigen (PSA).'),
    (v_topic_id, 'What is the "Florence Test" used for in forensic medicine?', '["To detect blood", "To detect seminal stains (based on the formation of dark-brown choline periodide crystals)", "To detect saliva", "To detect urine"]', 1, 'The Florence test is a classic microchemical test for semen. It reacts with choline to form characteristic rhombic crystals. It is a presumptive test, as it can occasionally give false positives.'),
    (v_topic_id, 'Spermatozoa can be identified in the vagina of a living victim for approximately how long after the assault?', '["1 hour", "Up to 3-4 days (72-96 hours), but they lose motility within 6-12 hours", "1 month", "Only if the victim was pregnant"]', 1, 'Non-motile sperm can be recovered for several days. Motile sperm are usually only found within the first 6-12 hours. In a deceased victim, sperm can persist for longer depending on the state of decomposition.'),
    (v_topic_id, 'DNA profiling in forensics primarily uses which technique to analyze small samples of biological evidence?', '["Western Blot", "Short Tandem Repeats (STR) analysis using Polymerase Chain Reaction (PCR)", "Northern Blot", "ELISA"]', 1, 'STR analysis targets specific regions of the DNA where short sequences repeat a variable number of times. PCR allows for the amplification of even tiny or degraded samples, making it the gold standard for forensic identification.'),
    (v_topic_id, 'In the medical examination of a sexual assault victim, the "Chain of Custody" refers to?', '["The victim''s family tree", "The meticulous documentation of every person who handles the evidence from the moment it is collected until it is presented in court", "The type of handcuffs used by the police", "The legal name of the suspect"]', 1, 'Maintaining the chain of custody is critical. If there is a gap in documentation, the evidence may be ruled inadmissible in court because its integrity cannot be guaranteed.'),

    -- FORENSIC: IDENTIFICATION (286-295)
    (v_topic_id, 'Dactylography (fingerprinting) is based on the fact that?', '["Everyone has different blood types", "Fingerprint patterns are unique to each individual and remain unchanged throughout life", "Fingerprints change with age", "Identical twins have the same fingerprints"]', 1, 'Fingerprint ridges (dermatoglyphics) are unique to every person, including identical twins. They are formed during fetal life and do not change unless the deep dermis is destroyed.'),
    (v_topic_id, 'What is the "Gustafson Method" used for in forensic identification?', '["Determining the sex from the pelvis", "Estimating the age of an adult by examining dental changes (e.g., attrition, root transparency, secondary dentin)", "Identifying blood types from saliva", "Matching fingerprints"]', 1, 'Gustafson''s method uses several dental criteria to estimate the age of an adult. Teeth are the hardest tissues in the body and are often the only remains available for identification after fires or advanced decomposition.'),
    (v_topic_id, 'The pelvis is the most reliable bone for determining the sex of a skeleton. Which feature is characteristic of a FEMALE pelvis?', '["Narrow, heart-shaped pelvic inlet", "Wide, oval-shaped pelvic inlet and a wider sub-pubic angle (> 90 degrees)", "Large, heavy bones", "Narrow greater sciatic notch"]', 1, 'The female pelvis is adapted for childbirth: it is lighter, wider, has a broader sub-pubic angle, and a wider sciatic notch. The male pelvis is narrower and heavier.'),
    (v_topic_id, 'Estimation of height from skeletal remains is typically done using?', '["The skull", "The length of long bones (especially the femur, tibia, and humerus) using standardized regression formulas like Pearson''s or Trotter and Gleser''s", "The width of the ribs", "The number of vertebrae"]', 1, 'The length of the long bones is highly correlated with an individual''s height. Multiplying the bone length by a specific factor or using regression equations provides an accurate estimate of stature.'),
    (v_topic_id, 'What is "Forensic Odontology"?', '["The study of ancient teeth", "The application of dental knowledge to the identification of human remains and the analysis of bite marks", "The treatment of dental diseases in prisoners", "The study of gum disease"]', 1, 'Forensic dentists play a key role in mass disasters where bodies are charred or fragmented. Bite marks can also be used to link a suspect to a crime, although this is more controversial.'),

    -- MEDICAL LAW & ETHICS (296-300)
    (v_topic_id, 'In medical law, "Battery" refers to?', '["Negligent treatment", "Any intentional, non-consensual physical contact with another person, including medical procedures performed without consent", "Failure to prescribe the correct medication", "Giving wrong advice"]', 1, 'Performing a procedure without consent, even if done skillfully and with good intentions, is legally considered battery. Consent must be "informed," meaning the patient understands the risks, benefits, and alternatives.'),
    (v_topic_id, 'What is the "Bolam Test" used for in medical law?', '["Determining if a patient is sane", "Assessing medical negligence: a doctor is not negligent if their actions are in accordance with a practice accepted as proper by a responsible body of medical professionals", "Testing for drugs in the blood", "Determining time of death"]', 1, 'The Bolam test (and the subsequent Bolitho modification) sets the standard for professional care. It essentially asks: "Would other competent doctors have done the same?"'),
    (v_topic_id, 'The "Privilege of Professional Secrecy" (Medical Confidentiality) can be legally breached in which situation?', '["To tell the patient''s employer about their illness", "When there is a significant risk of harm to the public (e.g., certain infectious diseases, suspected child abuse, or threats of violence)", "To gossip with other doctors", "To help a friend"]', 1, 'Confidentiality is a cornerstone of the doctor-patient relationship, but it is not absolute. Doctors are legally mandated to report "notifiable" diseases, suspected child or elder abuse, and must warn others if a patient makes a specific threat of violence (Tarasoff rule).'),
    (v_topic_id, 'What is the "Dying Declaration"?', '["A will written before death", "A statement made by a dying person who believes they are about to die, regarding the cause and circumstances of their death; it is admissible as evidence in court", "A final request for food", "A prayer"]', 1, 'A dying declaration is an exception to the "hearsay" rule. The law assumes that a person who knows they are dying will tell the truth. It must be recorded by a magistrate if possible, but a doctor can record it if death is imminent.'),
    (v_topic_id, 'Medical Malpractice (Negligence) requires four elements to be proven: Duty, Breach, Causation, and Damages. "Causation" means?', '["The doctor had a duty to the patient", "The doctor did not follow the standard of care", "The doctor''s breach of duty was the direct cause of the patient''s injury or harm", "The patient suffered physical or financial loss"]', 2, 'Even if a doctor made a mistake (breach of duty), if that mistake did not cause the actual harm the patient suffered, a malpractice claim cannot succeed. There must be a direct causal link.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
